const config = [
  [3, 101], [3, 211],
  [4, 307], [4, 419], [4, 523],
  [5, 601], [5, 709], [5, 811], [5, 907],
  [6, 1009], [6, 1117], [6, 1213], [6, 1319],
  [7, 1423], [7, 1523], [7, 1627], [7, 1721], [7, 1823],
];

const out = [];
const seenDeals = new Set();
config.forEach(([colors, seed], idx) => {
  const rng = mulberry32(seed);
  let best = null;
  for (let attempt = 0; attempt < 400; attempt++) {
    const hutches = colors + 2;
    const st = deal(colors, rng, hutches);
    if (looksTrivial(st)) continue;
    const dealKey = st.map((s) => s.join('')).join('|');
    if (seenDeals.has(dealKey)) continue;
    const res = solve(st, 600000);
    if (!res.ok) continue;
    if (!best || res.path.length < best.path.length) {
      best = { st: st.map((s) => s.slice()), path: res.path, nodes: res.nodes, dealKey };
    }
    if (best.path.length < 15) break;
  }
  if (!best) throw new Error('no level for ' + idx);
  seenDeals.add(best.dealKey);
  out.push({ colors, stacks: best.st, par: best.path.length, nodes: best.nodes });
  console.log(idx + 1, 'colors', colors, 'par', best.path.length, 'nodes', best.nodes, JSON.stringify(best.st));
});

