input.content:
/* ==========================================================================
   Hasen-Hoppel — cozy rabbit sorting game
   ========================================================================== */

:root {
  --ink: #3e2e22;
  --ink-soft: #7a6451;
  --cream: #fffaf0;
  --paper: #fffdf7;
  --accent: #ef8a49;
  --accent-deep: #cf692c;
  --accent-soft: #ffd7b5;
  --leaf: #6b9464;
  --leaf-deep: #4d7550;
  --gold: #f1b94f;
  --line: rgba(109, 79, 50, 0.16);
  --shadow-soft: 0 12px 30px rgba(88, 58, 32, 0.16);
  --shadow-strong: 0 22px 50px rgba(76, 48, 26, 0.26);
  --hutch-w: 82px;
  --hutch-h: 241px;
  --gap: 8px;
  --cols: 5;
  --font-round: "Avenir Next Rounded", "Nunito", "Segoe UI Rounded", "Trebuchet MS", "Verdana", sans-serif;
  --font-display: "Arial Rounded MT Bold", "Avenir Next Rounded", "Trebuchet MS", Georgia, serif;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
}

body {
  font-family: var(--font-round);
  color: var(--ink);
  background: #eaf2d9;
  overflow: hidden;
  overscroll-behavior: none;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  -webkit-tap-highlight-color: transparent;
}

button {
  font: inherit;
  color: inherit;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

button:focus-visible {
  outline: 3px solid #2f6f8f;
  outline-offset: 3px;
}

[hidden] { display: none !important; }

/* --------------------------------------------------------------------------
   Meadow backdrop
   -------------------------------------------------------------------------- */

.scene {
  position: fixed;
  inset: 0;
  z-index: -2;
  overflow: hidden;
  background:
    linear-gradient(180deg, #dff1fa 0%, #edf4e4 30%, #f5f0d4 52%, #e7edc9 70%, #d5e5b8 100%);
}

.sun {
  position: absolute;
  top: -130px;
  right: -90px;
  width: 430px;
  height: 430px;
  border-radius: 50%;
  background: radial-gradient(circle, #fff8c8 0%, #ffec9e 38%, rgba(255, 236, 158, 0.22) 63%, rgba(255, 236, 158, 0) 72%);
}

.cloud {
  position: absolute;
  width: 150px;
  height: 54px;
  border-radius: 100px;
  background: rgba(255, 255, 255, 0.82);
  filter: blur(1px);
  box-shadow: 0 12px 28px rgba(129, 158, 168, 0.1);
  animation: drift 26s ease-in-out infinite alternate;
}

.cloud::before,
.cloud::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  background: inherit;
}

.cloud::before {
  width: 70px;
  height: 70px;
  left: 22px;
  bottom: 10px;
}

.cloud::after {
  width: 92px;
  height: 92px;
  right: 20px;
  bottom: 2px;
}

.cloud-a { top: 7%; left: 6%; transform: scale(0.86); opacity: 0.86; }
.cloud-b { top: 16%; right: 13%; transform: scale(1.08); animation-delay: -9s; opacity: 0.75; }
.cloud-c { top: 2%; left: 46%; transform: scale(0.6); animation-delay: -17s; opacity: 0.55; }

.hill {
  position: absolute;
  left: -15%;
  width: 130%;
  border-radius: 50% 50% 0 0;
  filter: blur(0.5px);
}

.hill-back {
  bottom: -26%;
  height: 58%;
  background: linear-gradient(180deg, #cfdfa9, #c3d79b);
  transform: rotate(-1.5deg);
}

.hill-front {
  bottom: -34%;
  left: -30%;
  width: 160%;
  height: 52%;
  background: linear-gradient(180deg, #b8d293, #a9c784);
  transform: rotate(2deg);
}

.grass {
  position: absolute;
  inset: auto 0 0;
  height: 24%;
  background:
    repeating-linear-gradient(102deg, transparent 0 13px, rgba(75, 113, 61, 0.14) 13px 15px, transparent 15px 27px),
    linear-gradient(180deg, rgba(159, 193, 122, 0.06), #a5c27f 58%, #93b26d 100%);
  opacity: 0.9;
}

.flower {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: calc(5px * var(--s));
  height: calc(5px * var(--s));
  border-radius: 50%;
  background: #f4bd4e;
  opacity: 0.75;
  animation: sway 5.5s ease-in-out infinite alternate;
}

.flower::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: calc(4px * var(--s));
  height: calc(4px * var(--s));
  margin: calc(-2px * var(--s)) 0 0 calc(-2px * var(--s));
  border-radius: 50%;
  background: #fffdf4;
  box-shadow:
    0 calc(-7px * var(--s)) 0 #fffdf4,
    0 calc(7px * var(--s)) 0 #fffdf4,
    calc(-7px * var(--s)) 0 0 #fffdf4,
    calc(7px * var(--s)) 0 0 #fffdf4;
}

.butterfly {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: 12px;
  height: 10px;
  opacity: 0.55;
  animation: flutter 7s ease-in-out infinite;
}

.butterfly::before,
.butterfly::after {
  content: "";
  position: absolute;
  top: 0;
  width: 8px;
  height: 10px;
  border-radius: 80% 20% 70% 30%;
  background: #ffd1e0;
  border: 1px solid rgba(187, 112, 140, 0.4);
}

.butterfly::before { left: 0; transform: rotate(-18deg); }
.butterfly::after { right: 0; transform: scaleX(-1) rotate(-18deg); }

@keyframes drift {
  from { translate: -12px 0; }
  to { translate: 22px 8px; }
}

@keyframes sway {
  from { rotate: -6deg; }
  to { rotate: 7deg; }
}

@keyframes flutter {
  0%, 100% { translate: 0 0; }
  30% { translate: 18px -14px; }
  60% { translate: 34px 4px; }
  85% { translate: 12px 16px; }
}

/* --------------------------------------------------------------------------
   App shell
   -------------------------------------------------------------------------- */

.app {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100vh;
  height: 100dvh;
  padding:
    max(10px, env(safe-area-inset-top))
    max(12px, env(safe-area-inset-right))
    max(10px, calc(env(safe-area-inset-bottom) + 6px))
    max(12px, env(safe-area-inset-left));
}

.topbar {
  width: min(100%, 1180px);
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 0 0 auto;
  padding: 2px 2px 10px;
}

.level-title {
  min-width: 0;
  flex: 1 1 auto;
  padding-left: 2px;
}

.kicker {
  display: block;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--leaf-deep);
  opacity: 0.85;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.level-title h1 {
  margin: 1px 0 0;
  font-family: var(--font-display);
  font-size: clamp(18px, 2vw, 24px);
  line-height: 1.15;
  letter-spacing: -0.015em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
}

.icon-btn {
  flex: 0 0 auto;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(118, 87, 56, 0.18);
  border-radius: 15px;
  background: rgba(255, 252, 243, 0.82);
  box-shadow: 0 2px 0 rgba(255, 255, 255, 0.7) inset, 0 5px 14px rgba(91, 61, 35, 0.1);
  cursor: pointer;
  transition: transform 0.16s ease, background 0.16s ease, box-shadow 0.16s ease;
}

.icon-btn svg {
  width: 21px;
  height: 21px;
  fill: none;
  stroke: var(--ink);
  stroke-width: 1.9;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.icon-btn:hover { background: #fffdf7; transform: translateY(-1px); }
.icon-btn:active { transform: translateY(1px) scale(0.97); }
.icon-btn.small { width: 38px; height: 38px; border-radius: 12px; }
.icon-btn.small svg { width: 18px; height: 18px; }

.moves-pill {
  display: flex;
  align-items: baseline;
  gap: 6px;
  height: 44px;
  padding: 0 13px;
  border-radius: 15px;
  background: rgba(255, 252, 243, 0.82);
  border: 1px solid rgba(118, 87, 56, 0.18);
  box-shadow: 0 2px 0 rgba(255, 255, 255, 0.7) inset, 0 5px 14px rgba(91, 61, 35, 0.1);
}

.moves-label {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.moves-pill b {
  font-family: var(--font-display);
  font-size: 20px;
  line-height: 1;
  min-width: 1ch;
  text-align: center;
}

.moves-pill.bump b { animation: bump 0.28s ease; }

@keyframes bump {
  0% { transform: scale(1); }
  45% { transform: scale(1.35); color: var(--accent-deep); }
  100% { transform: scale(1); }
}

/* --------------------------------------------------------------------------
   Board & hutches
   -------------------------------------------------------------------------- */

.stage {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 2px 0;
}

.board {
  display: grid;
  grid-template-columns: repeat(var(--cols), var(--hutch-w));
  gap: var(--gap);
  justify-content: center;
  align-content: center;
  width: 100%;
  max-width: 100%;
  overflow: visible;
}

.hutch {
  position: relative;
  width: var(--hutch-w);
  height: var(--hutch-h);
  padding: 0;
  border: 0;
  border-radius: 15px 15px 9px 9px;
  background:
    repeating-linear-gradient(90deg, transparent 0 21%, rgba(92, 53, 25, 0.14) 21% 22.4%, transparent 22.4% 43%),
    linear-gradient(180deg, #d9a26e 0%, #c98a57 38%, #b57244 72%, #9d5f37 100%);
  box-shadow:
    0 2px 0 rgba(255, 255, 255, 0.3) inset,
    0 9px 0 rgba(94, 56, 29, 0.2),
    0 16px 26px rgba(71, 46, 24, 0.22);
  cursor: pointer;
  isolation: isolate;
  transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
}

.hutch::after {
  content: "";
  position: absolute;
  inset: 3% 5% auto;
  height: 6%;
  border-radius: 50%;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.26), transparent);
  pointer-events: none;
}

.hutch-inner {
  position: absolute;
  inset: 5.5% 8% 5%;
  border-radius: 46% 46% 7px 7px / 17% 17% 5px 5px;
  background:
    radial-gradient(ellipse at 50% 20%, #5c4634 0%, #423225 48%, #2e241c 82%, #241c16 100%);
  box-shadow:
    0 2px 0 rgba(255, 238, 210, 0.22),
    inset 0 12px 20px rgba(0, 0, 0, 0.55),
    inset 0 -12px 16px rgba(0, 0, 0, 0.34);
  overflow: hidden;
}

.hutch-inner::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 50% -18%, rgba(255, 213, 154, 0.16), transparent 60%),
    repeating-linear-gradient(74deg, transparent 0 11px, rgba(255, 255, 255, 0.02) 11px 12px);
  pointer-events: none;
}

.hutch-inner::after {
  content: "";
  position: absolute;
  inset: auto 0 0;
  height: 19%;
  border-radius: 0 0 7px 7px;
  background:
    repeating-linear-gradient(96deg, #ce9f4c 0 1.6px, transparent 1.6px 5.5px),
    repeating-linear-gradient(82deg, transparent 0 3px, rgba(105, 72, 27, 0.45) 3px 4.2px),
    linear-gradient(180deg, rgba(220, 177, 92, 0.62), rgba(163, 118, 55, 0.72));
  box-shadow: 0 -8px 14px rgba(34, 24, 16, 0.35);
  opacity: 0.9;
}

.bunny-slot {
  position: absolute;
  left: 15%;
  width: 70%;
  bottom: calc(7.5% + var(--i) * 28.2%);
  z-index: calc(4 + var(--i));
  transition: transform 0.18s cubic-bezier(0.2, 0.9, 0.3, 1.25);
  will-change: transform;
  pointer-events: none;
}

.bunny-slot svg {
  display: block;
  width: 100%;
  height: auto;
  filter: drop-shadow(0 3px 3px rgba(20, 12, 8, 0.4));
}

.hutch.is-selected .bunny-slot[data-top="1"] {
  transform: translateY(-7%) scale(1.03);
}

.hutch.is-selected {
  outline: 4px solid #ffb45f;
  outline-offset: 2px;
  box-shadow:
    0 0 0 8px rgba(255, 180, 95, 0.17),
    0 0 32px rgba(255, 176, 86, 0.48),
    0 9px 0 rgba(94, 56, 29, 0.2),
    0 18px 30px rgba(71, 46, 24, 0.25);
  transform: translateY(-4px);
}

.hutch.can-drop {
  box-shadow:
    0 0 0 4px #9bc47a,
    0 0 26px rgba(155, 196, 122, 0.72),
    0 9px 0 rgba(94, 56, 29, 0.2),
    0 16px 26px rgba(71, 46, 24, 0.22);
}

.hutch.can-drop .hutch-inner {
  box-shadow:
    0 2px 0 rgba(255, 238, 210, 0.3),
    inset 0 12px 20px rgba(0, 0, 0, 0.48),
    inset 0 0 22px rgba(189, 230, 148, 0.24),
    inset 0 -12px 16px rgba(0, 0, 0, 0.3);
}

.board.has-selection .hutch:not(.is-selected):not(.can-drop) {
  filter: saturate(0.72) brightness(0.93);
}

.hutch.empty .empty-hint {
  opacity: 0.7;
}

.empty-hint {
  position: absolute;
  left: 0;
  right: 0;
  top: 42%;
  z-index: 1;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  text-align: center;
  color: #d8c19b;
  opacity: 0;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.5);
  pointer-events: none;
  transition: opacity 0.2s ease;
}

.hutch.empty.can-drop .empty-hint {
  opacity: 0.95;
  color: #d8ecc2;
}

.hutch.enter .bunny-slot {
  animation: bunny-in 0.45s cubic-bezier(0.2, 0.9, 0.3, 1.2) both;
  animation-delay: calc(var(--i) * 40ms);
}

@keyframes bunny-in {
  from { opacity: 0; transform: translateY(38%) scale(0.7); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.hutch.shake {
  animation: shake 0.4s ease;
}

.hutch.nudge {
  animation: nudge 0.32s ease;
}

@keyframes shake {
  0%, 100% { translate: 0; }
  18% { translate: -6px 0; }
  38% { translate: 5px 0; }
  58% { translate: -4px 0; }
  78% { translate: 2px 0; }
}

@keyframes nudge {
  0%, 100% { translate: 0; }
  35% { translate: 0 -5px; }
  65% { translate: 0 1px; }
}

.hutch.hint-source {
  outline: 4px dashed #ffd277;
  outline-offset: 3px;
}

.hutch.hint-target {
  outline: 4px solid #ffd277;
  outline-offset: 3px;
  animation: hint-pulse 0.9s ease-in-out infinite alternate;
}

@keyframes hint-pulse {
  from { box-shadow: 0 0 0 4px rgba(255, 210, 119, 0.24), 0 9px 0 rgba(94, 56, 29, 0.2); }
  to { box-shadow: 0 0 0 8px rgba(255, 210, 119, 0.4), 0 0 30px rgba(255, 205, 105, 0.7), 0 9px 0 rgba(94, 56, 29, 0.2); }
}

.hutch.solved .bunny-slot {
  animation: happy-hop 0.65s ease both;
  animation-delay: calc(var(--i) * 70ms + 80ms);
}

@keyframes happy-hop {
  0%, 100% { transform: translateY(0); }
  35% { transform: translateY(-12%) rotate(-2deg); }
  60% { transform: translateY(-3%) rotate(1deg); }
  78% { transform: translateY(-7%); }
}

@media (hover: hover) and (pointer: fine) {
  .hutch:hover { transform: translateY(-3px); }
  .hutch.is-selected:hover { transform: translateY(-5px); }
}

/* Status line */

.status {
  flex: 0 0 auto;
  min-height: 22px;
  margin: 2px 0 0;
  padding: 0 10px;
  max-width: min(92vw, 640px);
  font-size: clamp(12px, 1.4vw, 14.5px);
  font-weight: 600;
  line-height: 1.35;
  color: var(--ink-soft);
  text-align: center;
  text-wrap: balance;
  transition: color 0.2s ease;
}

.status.warn { color: #a35d30; }
.status.good { color: var(--leaf-deep); }

/* Bottom controls */

.controls {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding-top: 4px;
}

.tool-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 42px;
  padding: 0 16px;
  border-radius: 14px;
  border: 1px solid rgba(118, 87, 56, 0.17);
  background: rgba(255, 252, 243, 0.82);
  box-shadow: 0 2px 0 rgba(255, 255, 255, 0.7) inset, 0 5px 14px rgba(91, 61, 35, 0.1);
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  transition: transform 0.16s ease, background 0.16s ease, opacity 0.16s ease;
}

.tool-btn svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: var(--ink);
  stroke-width: 1.9;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.tool-btn:hover { background: #fffdf7; transform: translateY(-1px); }
.tool-btn:active { transform: translateY(1px) scale(0.98); }
.tool-btn:disabled { opacity: 0.42; cursor: default; transform: none; }
.tool-btn.icon-only { width: 42px; padding: 0; }

#soundBtn .sound-off { display: none; }
#soundBtn[aria-pressed="false"] .sound-on { display: none; }
#soundBtn[aria-pressed="false"] .sound-off { display: block; }

/* --------------------------------------------------------------------------
   Overlays & modals
   -------------------------------------------------------------------------- */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding:
    max(16px, env(safe-area-inset-top))
    max(16px, env(safe-area-inset-right))
    max(16px, env(safe-area-inset-bottom))
    max(16px, env(safe-area-inset-left));
  background: rgba(64, 46, 30, 0.36);
  backdrop-filter: blur(7px) saturate(1.05);
  -webkit-backdrop-filter: blur(7px) saturate(1.05);
  animation: overlay-in 0.25s ease both;
}

@keyframes overlay-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

.modal {
  position: relative;
  width: min(94vw, 520px);
  max-height: min(90dvh, 780px);
  overflow: auto;
  padding: 26px 28px 24px;
  border-radius: 28px;
  border: 1px solid rgba(255, 255, 255, 0.85);
  background:
    radial-gradient(ellipse at 50% -15%, #fffdf6 0%, #fff9ea 48%, #fdf2dd 100%);
  box-shadow:
    0 2px 0 rgba(255, 255, 255, 0.9) inset,
    0 34px 80px rgba(57, 38, 21, 0.34),
    0 8px 20px rgba(57, 38, 21, 0.14);
  text-align: center;
  animation: modal-in 0.38s cubic-bezier(0.18, 0.9, 0.3, 1.15) both;
  scrollbar-width: thin;
}

@keyframes modal-in {
  from { opacity: 0; transform: translateY(18px) scale(0.96); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.hero-bunnies {
  display: flex;
  justify-content: center;
  align-items: flex-end;
  gap: 0;
  height: 96px;
  margin: -8px 0 2px;
}

.hero-bunnies .hero-bunny {
  width: 74px;
  margin: 0 -6px;
  filter: drop-shadow(0 7px 6px rgba(84, 53, 29, 0.18));
  animation: hero-bob 3.4s ease-in-out infinite;
}

.hero-bunnies .hero-bunny:nth-child(1) { transform: rotate(-6deg) translateY(7px); animation-delay: -0.8s; }
.hero-bunnies .hero-bunny:nth-child(2) { width: 88px; z-index: 2; }
.hero-bunnies .hero-bunny:nth-child(3) { transform: rotate(6deg) translateY(7px); animation-delay: -1.9s; }

@keyframes hero-bob {
  0%, 100% { translate: 0 0; }
  50% { translate: 0 -5px; }
}

.brand {
  margin: 4px 0 6px;
  font-size: 10.5px;
  font-weight: 900;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--accent-deep);
}

.modal h2 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(27px, 4.6vw, 36px);
  line-height: 1.08;
  letter-spacing: -0.022em;
  color: var(--ink);
}

.lede {
  margin: 12px auto 0;
  max-width: 390px;
  font-size: 14.5px;
  line-height: 1.52;
  color: var(--ink-soft);
}

.rules {
  list-style: none;
  margin: 18px 0 0;
  padding: 13px 15px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.56);
  border: 1px solid rgba(142, 106, 70, 0.13);
  text-align: left;
  display: grid;
  gap: 10px;
}

.rules li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 13px;
  line-height: 1.4;
  color: var(--ink-soft);
}

.rules b { color: var(--ink); }
.rules .rule-num {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: 21px;
  height: 21px;
  margin-top: -1px;
  border-radius: 50%;
  background: var(--accent-soft);
  color: #9c4f1e;
  font-size: 11px;
  font-weight: 900;
}

.intro-progress {
  min-height: 18px;
  margin: 13px 0 0;
  font-size: 12.5px;
  font-weight: 800;
  color: var(--leaf-deep);
}

.primary-btn {
  display: block;
  width: 100%;
  min-height: 52px;
  margin: 15px 0 0;
  padding: 0 22px;
  border: 0;
  border-radius: 17px;
  background: linear-gradient(180deg, #f7a25d 0%, #ef8a49 42%, #dd7136 100%);
  box-shadow:
    0 2px 0 rgba(255, 255, 255, 0.35) inset,
    0 7px 0 #b95a28,
    0 14px 24px rgba(190, 93, 40, 0.3);
  color: #fffdf8;
  font-family: var(--font-display);
  font-size: 18px;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.primary-btn:hover { transform: translateY(-1px); box-shadow: 0 2px 0 rgba(255,255,255,.35) inset, 0 8px 0 #b95a28, 0 17px 28px rgba(190, 93, 40, 0.34); }
.primary-btn:active { transform: translateY(4px); box-shadow: 0 2px 0 rgba(255,255,255,.3) inset, 0 3px 0 #b95a28, 0 8px 14px rgba(190, 93, 40, 0.28); }

.ghost-btn {
  min-height: 44px;
  padding: 0 22px;
  border: 1px solid rgba(122, 91, 59, 0.18);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.55);
  color: var(--ink-soft);
  font-size: 14px;
  font-weight: 800;
  cursor: pointer;
  transition: background 0.16s ease, transform 0.16s ease;
}

.ghost-btn:hover { background: #fffdf7; transform: translateY(-1px); }
.ghost-btn:active { transform: translateY(1px); }

.intro-modal > .ghost-btn {
  display: block;
  width: 100%;
  margin: 9px 0 0;
}

/* Levels modal */

.modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  text-align: left;
}

.modal-head h2 { font-size: clamp(24px, 4vw, 30px); }

.modal-sub {
  margin: 7px 0 16px;
  text-align: left;
  font-size: 13px;
  color: var(--ink-soft);
}

.level-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(94px, 1fr));
  gap: 9px;
}

.level-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-height: 86px;
  padding: 9px 6px 8px;
  border: 1px solid rgba(122, 91, 59, 0.16);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.62);
  box-shadow: 0 2px 0 rgba(255, 255, 255, 0.7) inset;
  cursor: pointer;
  transition: transform 0.16s ease, background 0.16s ease, box-shadow 0.16s ease;
}

.level-card:hover:not(:disabled) {
  transform: translateY(-2px);
  background: #fffdf8;
  box-shadow: 0 7px 16px rgba(91, 61, 35, 0.12);
}

.level-card.current {
  border-color: #e7a35d;
  background: #fff7e8;
  box-shadow: 0 0 0 2px rgba(239, 138, 73, 0.25);
}

.level-card.done {
  background: linear-gradient(180deg, #f6fae9, #eef5de);
  border-color: rgba(123, 153, 93, 0.28);
}

.level-card:disabled {
  cursor: default;
  opacity: 0.58;
  background: rgba(248, 243, 231, 0.48);
  box-shadow: none;
}

.level-num {
  font-family: var(--font-display);
  font-size: 20px;
  line-height: 1;
  color: var(--ink);
}

.level-card:disabled .level-num { color: #a79580; }

.level-name {
  max-width: 100%;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.03em;
  color: var(--ink-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.level-stars {
  display: flex;
  gap: 1px;
  height: 13px;
  margin-top: 2px;
  font-size: 11px;
  line-height: 1;
  color: #dcc9ab;
  letter-spacing: -0.05em;
}

.level-stars .on { color: var(--gold); }
.level-lock { height: 13px; margin-top: 3px; opacity: 0.55; }
.level-lock svg { width: 13px; height: 13px; fill: none; stroke: var(--ink-soft); stroke-width: 2; }

.level-best {
  font-size: 8.5px;
  font-weight: 800;
  color: var(--ink-soft);
  opacity: 0.75;
}

/* Win modal */

.win-bunnies {
  display: flex;
  justify-content: center;
  align-items: flex-end;
  height: 74px;
  margin: -4px 0 0;
}

.win-bunnies .win-bunny {
  width: 64px;
  margin: 0 -5px;
  filter: drop-shadow(0 6px 5px rgba(84, 53, 29, 0.18));
  animation: happy-hop 0.75s ease both;
}

.win-bunnies .win-bunny:nth-child(2) { width: 76px; z-index: 2; animation-delay: 0.1s; }
.win-bunnies .win-bunny:nth-child(3) { animation-delay: 0.2s; }

.star-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 48px;
  margin: 8px 0 2px;
}

.star {
  display: block;
  width: 40px;
  height: 40px;
  color: #e4d6bf;
  filter: drop-shadow(0 3px 2px rgba(94, 62, 30, 0.12));
  transform: scale(0.85);
}

.star.on {
  color: var(--gold);
  filter: drop-shadow(0 4px 6px rgba(230, 167, 47, 0.35));
  animation: star-pop 0.5s cubic-bezier(0.2, 1.3, 0.4, 1) both;
}

.star:nth-child(2) { animation-delay: 0.12s; }
.star:nth-child(3) { animation-delay: 0.24s; }

@keyframes star-pop {
  from { transform: scale(0.2) rotate(-20deg); opacity: 0; }
  to { transform: scale(1) rotate(0); opacity: 1; }
}

.win-text {
  margin: 2px auto 0;
  max-width: 340px;
  font-size: 14px;
  line-height: 1.45;
  color: var(--ink-soft);
  text-wrap: balance;
}

.win-secondary {
  display: flex;
  gap: 9px;
  margin-top: 10px;
}

.win-secondary .ghost-btn { flex: 1 1 0; }

/* Confetti canvas */

#confetti {
  position: fixed;
  inset: 0;
  z-index: 90;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

/* --------------------------------------------------------------------------
   Narrow screens
   -------------------------------------------------------------------------- */

@media (max-width: 520px) {
  .app {
    padding-left: max(8px, env(safe-area-inset-left));
    padding-right: max(8px, env(safe-area-inset-right));
  }

  .topbar { gap: 7px; padding-bottom: 7px; }
  .icon-btn { width: 40px; height: 40px; border-radius: 13px; }
  .moves-pill { height: 40px; padding: 0 10px; border-radius: 13px; gap: 4px; }
  .moves-pill b { font-size: 18px; }
  .moves-label { font-size: 9px; }
  .kicker { font-size: 9px; }
  .level-title h1 { font-size: 17px; }

  .controls { gap: 6px; }
  .tool-btn { height: 40px; padding: 0 12px; font-size: 12px; gap: 5px; border-radius: 12px; }
  .tool-btn.icon-only { width: 40px; }
  .tool-btn svg { width: 17px; height: 17px; }

  .status { font-size: 12px; min-height: 20px; }

  .modal { padding: 22px 18px 20px; border-radius: 24px; }
  .hero-bunnies { height: 82px; }
  .hero-bunnies .hero-bunny { width: 62px; }
  .hero-bunnies .hero-bunny:nth-child(2) { width: 74px; }
  .lede { font-size: 13.5px; }
  .rules { gap: 8px; padding: 11px 12px; }
  .rules li { font-size: 12.3px; }
  .primary-btn { min-height: 50px; font-size: 17px; }
  .level-grid { grid-template-columns: repeat(auto-fill, minmax(82px, 1fr)); gap: 7px; }
  .level-card { min-height: 80px; border-radius: 14px; }
  .level-name { font-size: 9px; }
}

@media (max-width: 370px) {
  .tool-btn span { display: none; }
  .tool-btn { width: 42px; padding: 0; }
  .tool-btn.icon-only { width: 42px; }
  .moves-label { display: none; }
  .level-title h1 { font-size: 16px; }
}

/* Small height: keep overlays comfortable */
@media (max-height: 620px) {
  .hero-bunnies { height: 70px; margin-top: -12px; }
  .hero-bunnies .hero-bunny { width: 56px; }
  .hero-bunnies .hero-bunny:nth-child(2) { width: 66px; }
  .lede { margin-top: 8px; }
  .rules { margin-top: 12px; }
  .modal { padding-top: 20px; padding-bottom: 18px; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

