import { createRequire } from 'node:module';
import fs from 'node:fs';
import path from 'node:path';

const require = createRequire(import.meta.url);
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');

// Load level data
globalThis.window = {};
await import('file:///home/runner/work/PlayGround/PlayGround/levels.js');
const LEVELS = globalThis.window.LEVELS;

const CAP = 3;
function solve(start) {
  const st = start.map((s) => s.slice());
  const seen = new Set();
  const moves = [];
  let nodes = 0;
  const solved = () => st.every((s) => !s.length || (s.length === CAP && s.every((c) => c === s[0])));
  const key = () => st.map((s) => s.join('')).sort().join('|');
  function dfs() {
    if (++nodes > 600000) return false;
    if (solved()) return true;
    const k = key();
    if (seen.has(k)) return false;
    seen.add(k);
    const options = [];
    for (let i = 0; i < st.length; i++) {
      const src = st[i];
      if (!src.length) continue;
      const c = src[src.length - 1];
      for (let j = 0; j < st.length; j++) {
        if (i === j) continue;
        const dst = st[j];
        if (dst.length >= CAP) continue;
        if (dst.length && dst[dst.length - 1] !== c) continue;
        if (!dst.length && src.every((x) => x === c)) continue;
        let score = 0;
        if (dst.length && dst[dst.length - 1] === c) score += 30;
        if (!dst.length) score -= 4;
        if (src.length === 1) score += 7;
        if (src.every((x) => x === c)) score -= 8;
        if (dst.length === CAP - 1) score += 9;
        options.push({ i, j, score });
      }
    }
    options.sort((a, b) => b.score - a.score);
    for (const o of options) {
      st[o.j].push(st[o.i].pop());
      moves.push([o.i, o.j]);
      if (dfs()) return true;
      moves.pop();
      st[o.i].push(st[o.j].pop());
    }
    return false;
  }
  return dfs() ? moves.slice() : null;
}

const solutions = new Map();
for (const level of LEVELS) {
  const t = Date.now();
  const sol = solve(level.stacks);
  if (!sol) throw new Error('unsolvable ' + level.id);
  solutions.set(level.id, sol);
  console.log(`level ${level.id}: par ${level.par}, solved ${sol.length} in ${Date.now() - t}ms`);
}

const browser = await chromium.launch({
  headless: true,
  executablePath: '/home/runner/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome',
  args: ['--no-sandbox']
});
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, reducedMotion: 'no-preference' });
const page = await context.newPage();
const pageErrors = [];
const consoleErrors = [];
page.on('pageerror', (e) => pageErrors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') consoleErrors.push(m.text()); });

const base = 'http://localhost:3002';
let failures = 0;
function check(ok, label) {
  if (!ok) { failures++; console.log('FAIL:', label); }
}

for (const level of LEVELS) {
  await page.goto(`${base}/?level=${level.id}&nointro=1`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.hutch');
  const info = await page.evaluate(() => ({
    count: document.querySelectorAll('.hutch').length,
    bunnies: document.querySelectorAll('.bunny-slot').length,
    kicker: document.querySelector('#levelKicker').textContent,
    board: (() => { const r = document.querySelector('#board').getBoundingClientRect(); return { top: r.top, bottom: r.bottom, left: r.left, right: r.right, width: r.width, height: r.height }; })(),
    header: document.querySelector('.topbar').getBoundingClientRect().bottom,
    controls: document.querySelector('.controls').getBoundingClientRect().top,
    status: document.querySelector('#status').textContent,
    overflowX: document.documentElement.scrollWidth > window.innerWidth,
  }));
  check(info.count === level.stacks.length, `level ${level.id} hutch count ${info.count}/${level.stacks.length}`);
  check(info.bunnies === level.colors * CAP, `level ${level.id} bunny count ${info.bunnies}`);
  check(info.kicker.includes(`Wiese ${level.id}`), `level ${level.id} kicker ${info.kicker}`);
  check(info.board.top >= info.header - 1, `level ${level.id} board collides with header (${info.board.top}/${info.header})`);
  check(info.board.bottom <= info.controls + 1, `level ${level.id} board collides with controls (${info.board.bottom}/${info.controls})`);
  check(!info.overflowX, `level ${level.id} horizontal overflow`);

  // Hint should find a move
  await page.click('#hintBtn');
  await page.waitForTimeout(120);
  const hintStatus = await page.textContent('#status');
  check(/^Tipp:/.test(hintStatus), `level ${level.id} hint: ${hintStatus}`);

  // Replay the known solution from a clean board
  await page.click('#restartBtn');
  await page.waitForTimeout(100);
  const sol = solutions.get(level.id);
  for (const [from, to] of sol) {
    await page.evaluate(([f, t]) => {
      const huts = document.querySelectorAll('.hutch');
      huts[f].click();
      huts[t].click();
    }, [from, to]);
    await page.waitForTimeout(15);
  }
  await page.waitForTimeout(900);
  const result = await page.evaluate(() => ({
    moves: document.querySelector('#movesCount').textContent,
    win: !document.querySelector('#winOverlay').hidden,
    status: document.querySelector('#status').textContent,
    stars: document.querySelector('#winStars').getAttribute('aria-label'),
    hutchStates: Array.from(document.querySelectorAll('.hutch')).map((h) => h.querySelectorAll('.bunny-slot').length),
  }));
  check(result.win, `level ${level.id} did not win (moves ${result.moves}, status ${result.status}, states ${JSON.stringify(result.hutchStates)})`);
  check(result.moves === String(sol.length), `level ${level.id} move count ${result.moves}/${sol.length}`);
  check(result.stars === '3 von 3 Sternen', `level ${level.id} stars ${result.stars}`);
  if (result.win) {
    await page.click('#nextBtn');
    await page.waitForTimeout(120);
  }
}

// Layout checks at other viewports
const layouts = [
  [1280, 800],
  [844, 390],
  [320, 568],
  [768, 1024],
];
for (const [w, h] of layouts) {
  await page.setViewportSize({ width: w, height: h });
  await page.goto(`${base}/?level=14&nointro=1`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(200);
  const fit = await page.evaluate(() => {
    const board = document.querySelector('#board').getBoundingClientRect();
    const header = document.querySelector('.topbar').getBoundingClientRect().bottom;
    const controls = document.querySelector('.controls').getBoundingClientRect().top;
    return {
      board: { top: board.top, bottom: board.bottom, left: board.left, right: board.right },
      header, controls,
      inner: [innerWidth, innerHeight],
      overflowX: document.documentElement.scrollWidth > innerWidth,
      overflowY: document.documentElement.scrollHeight > innerHeight,
    };
  });
  check(fit.board.top >= fit.header - 1, `layout ${w}x${h} top collision ${JSON.stringify(fit)}`);
  check(fit.board.bottom <= fit.controls + 1, `layout ${w}x${h} bottom collision ${JSON.stringify(fit)}`);
  check(fit.board.left >= -1 && fit.board.right <= w + 1, `layout ${w}x${h} horizontal bounds ${JSON.stringify(fit)}`);
  check(!fit.overflowX && !fit.overflowY, `layout ${w}x${h} scroll overflow ${JSON.stringify(fit)}`);
}

console.log('page errors:', pageErrors);
console.log('console errors:', consoleErrors);
check(pageErrors.length === 0, 'page errors');
check(consoleErrors.length === 0, 'console errors');
await browser.close();
console.log(failures === 0 ? 'ALL CHECKS PASSED' : `${failures} CHECK(S) FAILED`);
process.exit(failures === 0 ? 0 : 1);

