import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');

const browser = await chromium.launch({
  headless: true,
  executablePath: '/home/runner/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome',
  args: ['--no-sandbox']
});
const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
const page = await context.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));

const base = 'http://localhost:3002';
let failures = 0;
function check(ok, label) {
  if (!ok) { failures++; console.log('FAIL:', label); }
}

// Seed a corrupt/hostile save: level 10 last played, only level 2 unlocked.
await page.goto(base, { waitUntil: 'domcontentloaded' });
await page.evaluate(() => {
  localStorage.setItem('hasen-hoppel-v1', JSON.stringify({
    unlocked: 2, best: {}, lastLevel: 10, sound: true
  }));
});
await page.goto(base, { waitUntil: 'networkidle' });
await page.waitForSelector('.hutch');
let kicker = await page.textContent('#levelKicker');
check(/Wiese 2 von 18/.test(kicker), `normal reload clamps to unlocked level, got "${kicker}"`);

// URL preview of a locked level still works for testing.
await page.goto(`${base}/?level=18&nointro=1`, { waitUntil: 'networkidle' });
await page.waitForSelector('.hutch');
kicker = await page.textContent('#levelKicker');
check(/Wiese 18 von 18/.test(kicker), `?level=18 still previews locked level, got "${kicker}"`);

// That preview must not poison the next normal reload.
const saved = await page.evaluate(() => JSON.parse(localStorage.getItem('hasen-hoppel-v1')));
check(saved.lastLevel === 2, `locked preview keeps lastLevel at 2, got ${saved.lastLevel}`);
await page.goto(base, { waitUntil: 'networkidle' });
await page.waitForSelector('.hutch');
kicker = await page.textContent('#levelKicker');
check(/Wiese 2 von 18/.test(kicker), `reload after preview stays on level 2, got "${kicker}"`);

// Unlocked progress is respected.
await page.evaluate(() => {
  localStorage.setItem('hasen-hoppel-v1', JSON.stringify({
    unlocked: 7, best: {}, lastLevel: 7, sound: true
  }));
});
await page.goto(base, { waitUntil: 'networkidle' });
await page.waitForSelector('.hutch');
kicker = await page.textContent('#levelKicker');
check(/Wiese 7 von 18/.test(kicker), `unlocked level 7 loads, got "${kicker}"`);

check(errors.length === 0, `no page errors: ${JSON.stringify(errors)}`);
console.log(failures ? 'CLAMP CHECKS FAILED' : 'CLAMP CHECKS PASSED');
await browser.close();
process.exit(failures ? 1 : 0);

