import { createRequire } from 'node:module';
import fs from 'node:fs';
const require = createRequire(import.meta.url);
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');

const browser = await chromium.launch({
  headless: true,
  executablePath: '/home/runner/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome',
  args: ['--no-sandbox']
});
const base = 'http://localhost:3002';
const dir = '/home/runner/work/PlayGround/PlayGround/screenshots';
let failures = 0;
const check = (ok, label) => { if (!ok) { failures++; console.log('FAIL:', label); } };

for (const [name, viewport] of [['desktop', { width: 1280, height: 800 }], ['mobile', { width: 390, height: 844 }]]) {
  const context = await browser.newContext({ viewport, reducedMotion: 'no-preference' });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e)));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

  await page.goto(base, { waitUntil: 'networkidle' });
  check(await page.isVisible('#introOverlay'), `${name}: intro visible on fresh boot`);
  check(await page.isVisible('#startBtn'), `${name}: start button visible`);
  await page.screenshot({ path: `${dir}/final-intro-${name}.png` });

  await page.click('#startBtn');
  await page.waitForSelector('.hutch');
  await page.waitForTimeout(250);
  check(!(await page.isVisible('#introOverlay')), `${name}: intro closes`);
  check((await page.textContent('#levelKicker')).includes('Wiese 1'), `${name}: starts on level 1`);
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth + 1);
  check(!overflow, `${name}: no horizontal overflow`);
  await page.screenshot({ path: `${dir}/final-game-${name}.png` });
  check(errors.length === 0, `${name}: no console/page errors (${JSON.stringify(errors)})`);
  await context.close();
}

console.log(failures ? 'FINAL CHECKS FAILED' : 'FINAL CHECKS PASSED');
await browser.close();
process.exit(failures ? 1 : 0);
